function fromData(b64) {
 return new Promise((resolve,reject)=>{
   new THREE.TextureLoader().load('data:image/webp;base64,'+b64,t=>{
     t.colorSpace=THREE.SRGBColorSpace;
     t.anisotropy=8;
     t.wrapS=t.wrapT=THREE.ClampToEdgeWrapping;
     resolve(t);
   },undefined,reject);
 });
}
function crop(base,x1,y1,x2,y2){
 const t=base.clone();
 t.offset.set(x1/1024,1-y2/1024);
 t.repeat.set((x2-x1)/1024,(y2-y1)/1024);
 t.needsUpdate=true;
 return t;
}
const painted=map=>new THREE.MeshBasicMaterial({map,side:THREE.DoubleSide,depthWrite:true,toneMapped:false});
export async function applyPhotoMaterials(root){
 const [atlas,statue,roof]=await Promise.all([fromData(ATLAS64),fromData(STATUE64),fromData(ROOF64)]);
 const mural=root.getObjectByName('ACTUAL_THEME_INSPIRED_TROPICAL_MURAL');
 if(mural)mural.material=painted(crop(atlas,0,0,1024,392));
 const left=root.getObjectByName('SIGN_TIKI');
 const right=root.getObjectByName('SIGN_TAKI');
 if(left)left.material=painted(crop(atlas,0,648,512,888));
 if(right)right.material=painted(crop(atlas,512,648,1024,888));
 const booth=root.getObjectByName('TICKET_BOOTH');
 if(booth){
  // Avoid duplicate stylized geometry covering actual illustrated canopy.
  const hide=['SIGN_TICKETS','PURPLE_SCENIC_VOLCANO','LAVA_VOLCANO_CAP','V4_VOLCANO_IRREGULAR_LAVA_RIDGE','V4_BOOTH_FLOWER_PETAL','V4_BOOTH_SCENIC_LEAF','V4_BOOTH_HIBISCUS_HEART','ROOF_FLOWER'];
  booth.traverse(o=>{if(o.isMesh&&hide.some(h=>o.name.startsWith(h)))o.visible=false});
  const photoRoof=new THREE.Mesh(new THREE.PlaneGeometry(8.55,3.48),new THREE.MeshBasicMaterial({map:roof,side:THREE.DoubleSide,transparent:true,alphaTest:.08,depthWrite:false,toneMapped:false}));
  photoRoof.name='AUTHENTIC_TIKI_TAKI_TICKETS_CANOPY';photoRoof.position.set(0,6.54,2.47);booth.add(photoRoof);
  const front=booth.getObjectByName('SIGN_TIKI TAKI');
  if(front)front.visible=false;
  const kioskFront=new THREE.Mesh(new THREE.PlaneGeometry(7.62,4.1),painted(crop(atlas,512,400,1024,640)));
  kioskFront.name='AUTHENTIC_TIKI_TAKI_TICKET_WINDOWS_AND_FASCIA';
  kioskFront.position.set(0,2.56,2.52);booth.add(kioskFront);
 }
 const idol=root.getObjectByName('TIKI_CARVED_FRONT_IDOL');
 if(idol){
  // Hide only decorative low-poly parts; retain base stair structure.
  const preserveRelief=['TIKI_STONE_STAIR','CARVED_WOOD_TIKI_HEAD','WOODEN_IDOL_COLUMN','TIKI_STATUE_SIDE_RIB','TIKI_STATUE_CARVED_SIDE_RELIEF'];
   idol.traverse(o=>{if(o.isMesh&&!preserveRelief.some(name=>o.name.includes(name)))o.visible=false});
  const photoStatue=new THREE.Mesh(new THREE.PlaneGeometry(3.85,4.15),new THREE.MeshBasicMaterial({map:statue,transparent:true,alphaTest:.08,side:THREE.DoubleSide,depthWrite:false,toneMapped:false}));
  photoStatue.name='AUTHENTIC_TIKI_ENTRANCE_PHOTO_CUTOUT';photoStatue.position.set(0,2.31,1.05);idol.add(photoStatue);
 }
 const cab=root.getObjectByName('V4_OPERATOR_CABIN');
 if(cab){const cabinGlass=cab.getObjectByName('OPERATOR_CABIN_BLACK_WINDSCREEN');if(cabinGlass)cabinGlass.material=painted(crop(atlas,0,896,512,1024))}
 // Delete the generic, brightly colored plastic circles from badge art.
 root.traverse(o=>{
  if(o.isMesh && (o.name==='BADGE_FLOWER_PETAL'||o.name==='V4_LED_CHROME_BEZEL'))o.visible=false;
 });
 return {atlas,statue,roof};
}